function validate(doc){if(!doc||doc.schema!==SCHEMA||doc.version!==VERSION||doc.layoutVersion!==5||!doc.maps||typeof doc.maps!=='object'||Array.isArray(doc.maps))throw Error('Formato de layout incompatível.');const expected=Object.keys(baseline);if(Object.keys(doc.maps).length!==expected.length||expected.some(id=>!doc.maps[id]))throw Error('O arquivo deve conter os dois mundos e todos os interiores.');let nodes=0,totalTiles=0;function safe(v,d=0){if(++nodes>3000000||d>24)throw Error('Arquivo complexo demais.');if(typeof v==='number'&&!Number.isFinite(v))throw Error('Número inválido.');if(typeof v==='string'&&v.length>20000)throw Error('Texto longo demais.');if(v&&typeof v==='object')for(const [k,x] of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Chave proibida.');safe(x,d+1);}}safe(doc);for(const id of expected){const l=doc.maps[id],b=baseline[id];if(l.id!==id||l.world!==b.world||l.parent!==b.parent)throw Error('Identidade da cena inválida: '+id);if(!Array.isArray(l.bounds)||l.bounds.length!==4||l.bounds.some(n=>!Number.isFinite(n))||l.bounds[0]!==0||l.bounds[1]!==0||l.bounds[2]<256||l.bounds[3]<256||l.bounds[2]>20000||l.bounds[3]>20000)throw Error('Limites inválidos: '+id);const inside=(x,y)=>Number.isFinite(x)&&Number.isFinite(y)&&x>=0&&y>=0&&x<=l.bounds[2]&&y<=l.bounds[3];const ids=new Set();for(const group of ['objects','npcs','mobs','pickups']){const arr=l[group]||[];if(!Array.isArray(arr)||arr.length>12000)throw Error('Objetos demais em '+id);for(const o of arr){if(!o||!(/^[\w.:-]{1,120}$/).test(o.id)||ids.has(o.id)||!manifest[o.sprite]||!inside(o.x,o.y))throw Error('Objeto inválido em '+id);ids.add(o.id);if(doc.rpgVersion===1&&(group==='mobs'&&!o.definitionId||group==='pickups'&&!o.itemId||o.harvest&&!o.harvest.itemId))throw Error('Referência de definição ausente.');if(group==='mobs'&&o.definitionId&&!window.CHEMSCAPE_RPG.data.monsters[o.definitionId])throw Error('Definição de monstro inexistente.');if(group==='pickups'&&o.itemId&&!window.CHEMSCAPE_RPG.data.items[o.itemId])throw Error('Definição de item inexistente.');if(o.overrides&&group==='mobs'){const R=window.CHEMSCAPE_RPG,d=R.monster(o,l.world),doc=R.clone(R.data);doc.monsters[d.id]=d;R.validateDefinitions(doc);}if(o.quantity!==undefined&&(!Number.isInteger(o.quantity)||o.quantity<1||o.quantity>999))throw Error('Quantidade inválida.');if(o.scale!==undefined&&(typeof o.scale!=='number'||o.scale<.1||o.scale>8))throw Error('Escala inválida.');if(o.rotation!==undefined&&(!Number.isFinite(o.rotation)||Math.abs(o.rotation)>360000))throw Error('Rotação inválida.');if(o.depthY!==undefined&&(!Number.isFinite(o.depthY)||Math.abs(o.depthY)>40000))throw Error('Profundidade inválida.');if(o.solid&&(!Array.isArray(o.solid)||o.solid.length!==4||o.solid.some(n=>!Number.isFinite(n))||o.solid[2]<=0||o.solid[3]<=0||o.solid.some(n=>Math.abs(n)>4000)))throw Error('Colisão inválida.');if(o.enter&&!doc.maps[o.enter])throw Error('Interior inexistente.');if(o.door&&(!Array.isArray(o.door)||!inside(...o.door)))throw Error('Porta fora da cena.');if(o.lines&&(!Array.isArray(o.lines)||o.lines.length>64||o.lines.some(s=>typeof s!=='string'||s.length>4000)))throw Error('Diálogo inválido.');if(o.path&&(!Array.isArray(o.path)||o.path.length>128||o.path.some(p=>!Array.isArray(p)||p.length!==2||!inside(...p))))throw Error('Rota inválida.');}l[group]=arr;}for(const point of ['spawn','labDoor','slime','crystal','portal','returnSpawn','exit'])if(l[point]&&(!Array.isArray(l[point])||l[point].length!==2||!inside(...l[point])))throw Error('Ponto fora da cena: '+point);if(!l.floor||l.floor.size!==b.floor.size||!same(l.floor.files,b.floor.files))throw Error('Os recursos originais do chão devem ser preservados.');l.floor=clone(b.floor);for(const key of ['obstacles','editorBlocks']){const arr=l[key]||[];if(!Array.isArray(arr)||arr.length>20000)throw Error('Bloqueios demais.');for(const r of arr)if(!inside(r.x,r.y)||!Number.isFinite(r.w)||!Number.isFinite(r.h)||r.w<=0||r.h<=0||r.x+r.w>l.bounds[2]+1||r.y+r.h>l.bounds[3]+1)throw Error('Bloqueio fora do mapa.');}if(l.paint){if(l.paint.version!==1||!l.paint.tiles||typeof l.paint.tiles!=='object'||Array.isArray(l.paint.tiles))throw Error('Pintura inválida.');const entries=Object.entries(l.paint.tiles);if(entries.length>MAX_TILES||(totalTiles+=entries.length)>350000)throw Error('Pintura grande demais.');for(const [k,t] of entries){const a=k.split(':').map(Number);if(a.length!==3||!Number.isInteger(a[0])||a[0]<8||a[0]>1536||a[0]%8!==0||Math.abs(a[1]*a[0]-Math.round(a[1]*a[0]))>1e-6||Math.abs(a[2]*a[0]-Math.round(a[2]*a[0]))>1e-6||!inside(a[0]*a[1],a[0]*a[2])||!floors[t.type]||!/^#[0-9a-f]{6}$/i.test(t.color)||t.order!==undefined&&(!Number.isFinite(t.order)||t.order<0||t.order>1e12))throw Error('Célula de piso inválida.');if(t.circle&&(!Array.isArray(t.circle)||t.circle.length!==3||t.circle.some(n=>!Number.isFinite(n))||t.circle[2]<=0||t.circle[2]>768||t.circle[0]<0||t.circle[1]<0||t.circle[0]>l.bounds[2]+768||t.circle[1]>l.bounds[3]+768))throw Error('Círculo de piso inválido.');if(t.texture&&!window.CHEMSCAPE_FLOOR_TEXTURES.valid(t.texture))throw Error('Textura de piso inválida.');if(t.type==='original'&&!t.texture)throw Error('Piso original sem textura.');}}}return clone(doc.maps);}
