function exportJs(){const data=clone(E.levels());data.version=5;data.release='7.2 Conta-gotas de Objetos';download('level_data.js','window.CHEMSCAPE_LEVELS = '+JSON.stringify(data)+';\n','text/javascript');status('level_data.js exportado. Substitua o arquivo de mesmo nome no projeto.');}
function modal(title,text,action,label='Confirmar'){$('ce-modal-title').textContent=title;$('ce-modal-text').textContent=text;$('ce-modal-ok').textContent=label;modalCallback=action;$('ce-modal').classList.add('open');}
$('ce-modal-cancel').onclick=()=>{$('ce-modal').classList.remove('open');modalCallback=null;};$('ce-modal-ok').onclick=()=>{const fn=modalCallback;$('ce-modal').classList.remove('open');modalCallback=null;fn?.();};
