function inspectorMarkup(){const list=selected();if(!list.length)return '<p class="ce-help">Escolha um asset e clique no mapa para adicionar. Clique em um objeto para editar. Shift permite seleção múltipla.</p>';if(list.length>1)return `<h3>${list.length} elementos selecionados</h3><p>Mova os elementos juntos, duplique ou remova a seleção.</p><div class="ce-actions"><button id="ce-duplicate">Duplicar</button><button id="ce-delete" class="danger">Remover</button></div>`;const s=list[0],o=s.o,solid=o.solid||[-16,-16,32,24];return `<h3>Propriedades · ${s.group==='npcs'?'NPC':s.group==='mobs'?'Criatura':kindLabels[o.kind]||'Objeto'}</h3><div class="ce-field-id">ID preservado: ${esc(o.id)}</div><label>Nome</label><input id="ce-name" value="${esc(o.name||'')}"><div class="ce-triple" style="margin-top:8px"><div><label>X</label><input id="ce-x" type="number" step="1" value="${Math.round(o.x*100)/100}"></div><div><label>Y</label><input id="ce-y" type="number" step="1" value="${Math.round(o.y*100)/100}"></div><div><label>Escala</label><input id="ce-scale" type="number" step="0.05" min="0.1" max="8" value="${typeof o.scale==='number'?o.scale:1}"></div></div><div class="ce-pair"><div><label>Rotação · graus</label><input id="ce-rotation" type="number" step="1" value="${o.rotation||0}"></div><div><label>Profundidade · Y</label><input id="ce-depth" type="number" placeholder="Automática" value="${o.depthY??''}"></div></div><div class="ce-checks">${[['flipX','Espelhar X'],['flipY','Espelhar Y'],['hidden','Ocultar'],['locked','Travar']].map(([id,label])=>`<label><input data-property="${id}" type="checkbox" ${o[id]?'checked':''}>${label}</label>`).join('')}</div><div class="ce-checks"><label><input id="ce-solid" type="checkbox" ${o.solid?'checked':''}>Área sólida</label></div><div class="ce-pair"><div><label>Colisão · X local</label><input data-solid="0" type="number" value="${solid[0]}" ${o.solid?'':'disabled'}></div><div><label>Colisão · Y local</label><input data-solid="1" type="number" value="${solid[1]}" ${o.solid?'':'disabled'}></div><div><label>Largura sólida</label><input data-solid="2" type="number" min="1" value="${solid[2]}" ${o.solid?'':'disabled'}></div><div><label>Altura sólida</label><input data-solid="3" type="number" min="1" value="${solid[3]}" ${o.solid?'':'disabled'}></div></div>${o.door?`<div class="ce-muted">Porta: ${Math.round(o.door[0])}, ${Math.round(o.door[1])} · acompanha a estrutura</div>`:''}${s.group==='npcs'?`<label>Prévia da animação</label><select id="ce-preview">${options(["","stand","walk","attack","work"],o.previewAnimation||"",{"":"Jogo",stand:"Stand",walk:"Walk",attack:"Attack",work:"Trabalho"})}</select><label>Atividade</label><select id="ce-activity">${options(["idle","guard","work","training"],o.activity||(o.path?.length?"guard":"idle"),{idle:"Repouso",guard:"Patrulha",work:"Trabalho",training:"Treinamento"})}</select><label>Falas · uma por linha</label><textarea id="ce-lines" rows="4">${esc((o.lines||E.dialogue(o.id)||[]).join('\n'))}</textarea><label style="margin-top:8px">Rotina · X,Y por linha</label><textarea id="ce-path" rows="3" placeholder="1200,800\n1320,800">${esc((o.path||[]).map(p=>p.join(',')).join('\n'))}</textarea><p>Alterar posição preserva falas e identidade. Alterar o texto substitui apenas a conversa deste NPC.</p>`:''}${s.group==='mobs'?`<div class="ce-rpg-link"><small>Template: ${esc(o.definitionId||'Legado')} · ${Object.keys(o.overrides||{}).length?'com sobrescritas':'vinculado'}</small><button id="ce-edit-monster-template">Editar template</button><button id="ce-edit-monster-instance">Sobrescritas da instância</button></div>`:s.group==='pickups'?`<div class="ce-rpg-link"><small>Item: ${esc(o.itemId||o.name)} · quantidade ${o.quantity||1}</small><button id="ce-edit-item-template">Editar item</button><button id="ce-edit-item-instance">Pickup no mapa</button></div>`:''}<div class="ce-actions"><button id="ce-duplicate">Duplicar</button><button id="ce-delete" class="danger">Remover</button><button id="ce-focus">Centralizar</button></div>`;}
function sceneMarkup(){const l=level();return `<h3>Configuração da cena</h3><label>Nome</label><input id="ce-scene-name" value="${esc(l.name||l.id)}"><div class="ce-pair" style="margin-top:9px"><div><label>Largura do mapa</label><input id="ce-width" type="number" min="256" max="20000" value="${l.bounds[2]}"></div><div><label>Altura do mapa</label><input id="ce-height" type="number" min="256" max="20000" value="${l.bounds[3]}"></div></div><h3>Entradas e pontos da história</h3>${[['spawn','Início'],['labDoor','Porta AION'],['slime','Slime inicial'],['crystal','Cristal'],['portal','Portal'],['returnSpawn','Retorno'],['exit','Saída'],['parentSpawn','Retorno ao exterior']].filter(([id])=>l[id]).map(([id,label])=>`<label>${label}</label><div class="ce-pair"><input data-point="${id}" data-axis="0" aria-label="${label} X" type="number" value="${l[id][0]}"><input data-point="${id}" data-axis="1" aria-label="${label} Y" type="number" value="${l[id][1]}"></div>`).join('')}<div class="ce-checks"><label><input id="ce-points" type="checkbox" ${showPoints?'checked':''}>Ver pontos da história</label><label><input id="ce-collision" type="checkbox" ${showCollision?'checked':''}>Ver colisões</label></div><h3>Layout completo</h3><p>Os arquivos incluem os dois mundos e todos os interiores. A campanha e o inventário têm salvamentos independentes.</p><div class="ce-actions"><button id="ce-export-json">Exportar JSON</button><button id="ce-import">Importar JSON</button></div><div class="ce-actions"><button id="ce-export-js">Exportar level_data.js</button></div><div class="ce-actions"><button id="ce-reset-scene" class="danger">Restaurar esta cena</button><button id="ce-reset-all" class="danger">Restaurar tudo</button></div>`;}
